export const chapters = [];
let rows;
const chapter=(name,description)=>{rows=[];chapters.push({name,description,rows});};
let num=0;
const add=(action,cmd,before,steps,result,pitfall,refs)=>rows.push({id:++num,action,cmd,before,steps:steps.map((s,i)=>`${i+1}. ${s}`).join('\n'),result,pitfall,refs});
chapter('01 התחלה וסקיצות','התחילו בקובץ חדש; בנו סקיצה פשוטה עם מידות ואילוצים לפני יצירת נפח.');
add('פתיחת תכנון מתאים','File > New Design','בחרו מה בונים: חלק יחיד, מכלול או כמה חלקים בתוך קובץ.', ['פתחו New Design.','בחרו Part לחלק יחיד; Assembly להרכבת חלקים; Hybrid לשילוב מידול ומכלול.','אשרו ובדקו את סוג התכנון ב־Browser.','שמרו בשם שמתאר את החלק.'],'סביבת עבודה שמתאימה למשימה. לתרגילי חלק בודד בחרו Part.','אם כלי המידול חסרים במכלול, עברו לעריכת החלק או ל־Hybrid לפי הצורך.',['S02']);
add('יחידות ושמירה','Document Settings > Units; Save','תכנון חדש. דוגמאות המדריך במילימטרים.', ['פתחו Document Settings ובדקו Units.','בחרו mm למסמך.','לחצו Save ובחרו פרויקט ותיקייה.','פתחו את התיקייה בלחיצה כפולה לפני השמירה.'],'שם הקובץ מופיע והתיקייה הנכונה נבחרה.','שינוי יחידות תצוגה אינו תיקון לגאומטריה שיובאה בקנה מידה שגוי.',['P1']);
add('סיבוב, הזזה וקירוב המבט','Orbit / Pan / Zoom','עכבר עם גלגלת; הגדרות ניווט ברירת מחדל.', ['גללו לקירוב והרחקה.','החזיקו גלגלת וגררו להזזת המבט.','החזיקו Shift וגלגלת וגררו לסיבוב.','בחרו פאה ב־ViewCube למבט ישר.'],'המצלמה זזה; מיקום החלק אינו משתנה.','בפרופיל ניווט אחר הקיצורים עשויים להשתנות.',['S01']);
add('איתור פקודה והסתרת פריט','S / Browser visibility','היו בסביבת העבודה המתאימה.', ['לחצו Esc ליציאה מפקודה.','לחצו S והקלידו את שם הכלי באנגלית.','בחרו בתוצאת החיפוש.','להסתרת סקיצה או גוף השתמשו בסמל הנראות ב־Browser.'],'אפשר למצוא כלי גם אם אינו מוצג בסרגל.','קיצור לא פועל כאשר הסמן נמצא בתוך שדה טקסט.',['S01','P1']);
add('יצירת סקיצה','Create Sketch','רכיב פעיל ומישור מתאים או פאה שטוחה.', ['הפעילו Create Sketch.','בחרו XY, XZ, YZ או פאה שטוחה.','בדקו שהמבט ניצב למישור.','בסיום הגאומטריה לחצו Finish Sketch.'],'סקיצה מופיעה בתיקיית Sketches.','סקיצה על פאה שעלולה להימחק יוצרת תלות באותה פאה.',['P1','P4']);
add('שרטוט קו ומלבן','Sketch > Create > Line / Rectangle','סקיצה פתוחה.', ['בחרו Line או 2-Point Rectangle.','התחילו ב־Origin כדי לעגן מיקום.','בחרו נקודות קצה או הקלידו מידות; Tab מחליף שדה.','לחצו Esc לסיום הפקודה.'],'קווים או מלבן עם קשר לראשית.','מראה ישר אינו מוכיח שיש אילוץ אופקי או אנכי.',['P1','P14']);
add('עיגול במידה מוגדרת','Center Diameter Circle; C','סקיצה פתוחה.', ['הפעילו Circle.','בחרו נקודת מרכז.','הקלידו קוטר ואשרו.','הגדירו גם מיקום מרכז ביחס לראשית או לקצוות.'],'הקוטר והמיקום נשלטים.','קוטר מוגדר לבדו משאיר למרכז חופש תנועה.',['P1','S04']);
add('קשת משיקה','Sketch > Create > Arc > Tangent Arc','קצה של קו או קשת קיימת.', ['הפעילו Tangent Arc דרך S.','בחרו בקצה הגאומטריה הקיימת.','בחרו את קצה הקשת החדש.','בדקו שיש קשר Tangent במעבר.'],'מסלול עם מעבר חלק, למשל ל־Sweep.','שני קצוות שנראים נוגעים עדיין עלולים להיות לא מחוברים.',['P3']);
add('קווי עזר','Sketch Palette > Construction; X','סקיצה פתוחה עם קו עזר רצוי.', ['בחרו קו.','לחצו X כדי להפוך אותו ל־Construction.','השתמשו בו כציר או כקו סימטריה.','בדקו שהוא מקווקו ואינו יוצר אזור מילוי.'],'קו עזר שמכוון גאומטריה בלי להוסיף פרופיל.','קו המתאר שאמור לסגור נפח לא צריך להיות קו עזר.',['P3','S01']);
add('הוספת מידה ושינויה','Sketch Dimension; D','סקיצה פתוחה וגאומטריה קיימת.', ['לחצו D ובחרו קו, מעגל או זוג ישויות.','לחצו למיקום הכיתוב.','הקלידו ערך ואשרו.','לשינוי לחצו פעמיים על המידה.'],'הגאומטריה מתעדכנת לפי הערך.','אם המידה יוצרת הגדרת יתר, בדקו קודם אילוץ או מידה קיימים.',['P13','S04']);
add('חיבור נקודות','Sketch > Constraints > Coincident','בחרו נקודות שאמורות להתחבר.', ['הפעילו Coincident.','בחרו נקודת קצה ראשונה.','בחרו נקודה שנייה או קו שאליו היא תוצמד.','גררו בעדינות ובדקו שהקשר נשמר.'],'נקודות מתלכדות או נקודה נשארת על קו.','נקודה על קו יכולה עדיין לנוע לאורכו.',['P14']);
add('כיוון ומקביליות','Horizontal/Vertical; Parallel; Perpendicular','קווים בסקיצה פתוחה.', ['בחרו Horizontal/Vertical לקו שאמור להיות ישר לצירים.','לשני קווים בכיוון זהה בחרו Parallel.','לזווית ישרה בין קווים בחרו Perpendicular.','גררו ובדקו שהקשרים נשמרים.'],'הכיוון נשלט גם לאחר שינוי מידות.','אל תוסיפו קשר שכבר נובע מאילוצים אחרים.',['S05']);
add('שוויון, מרכז וסימטריה','Equal; Midpoint; Concentric; Symmetry','סקיצה עם זוג גופים גאומטריים או קו סימטריה.', ['בחרו Equal ואז שני קווים או שני מעגלים לשוויון גודל.','בחרו Midpoint ואז נקודה וקו למרכוז.','בחרו Concentric ושני מעגלים למרכז משותף.','לסימטריה בחרו זוג ישויות וקו סימטריה.'],'הקשרים נשמרים בלי להכפיל מידות.','Equal אינו קובע מיקום; Concentric אינו קובע קוטר.',['S05']);
add('הגדרה מלאה של סקיצה','Dimensions + Constraints','סקיצה שנועדה לשלוט במודל פרמטרי.', ['עיגנו נקודה לראשית.','הוסיפו אילוצים שמתארים את הצורה.','השלימו מידות חסרות.','בדקו סמל מנעול והיעדר תנועה לא מתוכננת.'],'סקיצה מוגדרת; בגוון ברירת מחדל הגאומטריה המוגדרת שחורה.','Fix נועל צורה קיימת אך אינו מחליף כוונת תכנון באמצעות מידות.',['S04','P13']);
add('תיקון סקיצה בהגדרת יתר','Edit Sketch; Delete constraint','הופיעה הודעת Over-constrained.', ['בטלו את התוספת האחרונה.','בחרו באזור הבעייתי והציגו אילוצים.','זהו קשר כפול או מידה סותרת והסירו רק אותו.','נסו שוב ובדקו שהסקיצה עדיין מייצגת את הכוונה.'],'אפשר לערוך את המידה בלי הודעת סתירה.','אל תמחקו את כל האילוצים כדי להשתיק את ההודעה.',['P14']);
add('היטל מגאומטריה קיימת','Sketch > Create > Project/Include > Project','סקיצה פתוחה וקצה או פאה לשימוש כייחוס.', ['הפעילו Project.','בחרו קצוות, נקודות או גוף בעזרת מסנן מתאים.','השאירו Projection Link לקשר שמתעדכן.','אשרו והשתמשו בגאומטריה המוקרנת.'],'נוצר ייחוס סגול במישור הסקיצה.','מחיקת המקור עלולה לנתק את ההיטל; בדקו Manage Lost Projections.',['S07']);
add('היסט פרופיל','Sketch > Modify > Offset; O','סקיצה פתוחה עם עקומה או שרשרת.', ['הפעילו Offset.','בחרו את השרשרת הרצויה.','הגדירו מרחק וכיוון.','אשרו ובדקו את הקשר לפרופיל המקורי.'],'קונטור נוסף במרחק מוגדר.','היסט גדול באזור צר עשוי לגרום לחיתוך עצמי.',['S06']);
add('חיתוך והארכת קווים','Sketch > Modify > Trim / Extend','סקיצה עם קווים מצטלבים.', ['ב־Trim רחפו מעל הקטע להסרה.','בדקו תצוגה מקדימה ולחצו.','ב־Extend בחרו קצה להארכה עד מפגש.','בדקו שוב סגירת פרופיל ומידות.'],'גאומטריה נקייה ללא עודפים.','חיתוך יכול להסיר קשרים; ודאו שהמידות החשובות נשמרו.',['S06']);
add('תמונה כבסיס וכיול','Insert > Canvas; Calibrate','תמונה ומידה אמיתית ידועה בין שתי נקודות.', ['הכניסו Canvas ובחרו מישור.','ב־Browser לחצו ימנית על התמונה ובחרו Calibrate.','בחרו שתי נקודות והקלידו את המרחק האמיתי.','בדקו מידה נוספת לפני העתקת מתאר.'],'קנה מידה מכויל במישור התמונה.','צילום פרספקטיבי אינו שרטוט מדויק גם אחרי כיול.',['P2']);
chapter('02 מידול ופרמטרים','בנו את הצורה העיקרית, הוסיפו פרטים ובדקו שינוי מידות לפני הכנת שרטוט.');
add('יצירת נפח מסקיצה','Solid > Create > Extrude; E','פרופיל סגור במישור אחד.', ['סיימו את הסקיצה ובחרו Extrude.','בחרו את שטח הפרופיל.','הגדירו Distance וכיוון.','בחרו New Body או Join ואשרו.'],'נפח חדש או תוספת לגוף קיים.','בדקו Operation; בחירת Join יכולה לחבר גופים שלא התכוונתם לחבר.',['S08']);
add('כיס או חור דרך כל העובי','Extrude > Cut > All','גוף קיים ופרופיל חיתוך.', ['בחרו פרופיל ב־Extrude.','הגדירו Cut.','בחרו All לחור עובר או Distance לכיס.','בדקו את הכיוון ואת Objects to Cut ואשרו.'],'חומר הוסר מהגופים הרצויים.','מרחק שלילי לבדו אינו הוכחה שהוגדרה פעולת Cut.',['S08','P6']);
add('הבלטה סימטרית או עד פאה','Extrude > Symmetric / To Object','סקיצה וגאומטריית יעד במקרה הצורך.', ['בחרו פרופיל והפעילו Extrude.','לסימטריה בחרו Symmetric.','בדקו Half Length לעומת Whole Length.','לסיום לפי פאה בחרו To Object ובחרו יעד.'],'הנפח נשאר ממורכז או מסתיים ביחס ליעד.','ב־Half Length הערך חל לכל צד; העובי הכולל כפול.',['S08']);
add('גוף סיבובי','Solid > Create > Revolve','חתך סגור וציר שאינו חוצה את פנים החתך.', ['הפעילו Revolve ובחרו את שטח החתך.','בחרו קו או ציר בתור Axis.','הגדירו זווית, למשל 360 מעלות.','בחרו Operation ואשרו.'],'גוף צירי כגון שרוול או ציר מדורג.','בחרו את ציר הרכיב הנכון; ציר שגוי משנה לחלוטין את הצורה.',['S09','P2']);
add('נפח לאורך מסלול','Solid > Create > Sweep','חתך ונתיב רציף, רצוי חתך ניצב לתחילת הנתיב.', ['הכינו סקיצה לנתיב וסקיצה לחתך.','הפעילו Sweep ובחרו Profile.','בחרו Path ובדקו כיוון.','בחרו Operation ואשרו.'],'נפח הנע לאורך המסלול.','חתך גדול ביחס לרדיוס הפנייה עלול להתנגש בעצמו.',['S09','P3']);
add('מישור במרחק מוגדר','Construct > Offset Plane','מישור מקור או פאה שטוחה.', ['הפעילו Offset Plane.','בחרו מישור ייחוס.','הקלידו מרחק עם כיוון מתאים.','אשרו ופתחו סקיצה על המישור החדש.'],'מישור עבודה למפלס נוסף.','היסט מפאה משתנה תלוי בה; השתמשו במישור Origin כשהוא הייחוס הנכון.',['P4']);
add('מעבר בין חתכים','Solid > Create > Loft','שני פרופילים סגורים או יותר על מישורים שונים.', ['הפעילו Loft.','בחרו פרופילים בסדר החיבור.','הוסיפו Rails רק אם צריך לשלוט במעטפת.','בדקו תצוגה מקדימה ואשרו.'],'מעבר רציף בין החתכים.','כל Rail צריך לפגוש את כל החתכים; בדקו שאין פיתול.',['S09','P4']);
add('עיגול פינות','Solid > Modify > Fillet; F','גוף עם קצוות לעיגול.', ['הפעילו Fillet ובחרו קצוות.','בחרו רדיוס Constant והקלידו ערך.','בדקו אם Tangent Chain בחר קצוות נוספים.','אשרו ובחנו את הפינות.'],'קצוות מעוגלים ברדיוס המבוקש.','אם הפעולה נכשלת, נסו רדיוס קטן יותר או חלקו את הבחירה לקבוצות.',['S10']);
add('פאזה בקצה','Solid > Modify > Chamfer','קצה חיצוני או שפת חור.', ['הפעילו Chamfer.','בחרו את הקצה.','בחרו סוג, למשל Distance and Angle.','הקלידו מרחק וזווית ואשרו.'],'משטח משופע לאורך הקצה.','פאזה אינה רדיוס; בדקו מאיזה צד נמדד המרחק.',['P6']);
add('חלול גוף','Solid > Modify > Shell','גוף מלא שממנו רוצים ליצור דפנות.', ['הפעילו Shell.','בחרו פאה להסרה, או גוף לחלל סגור.','בחרו Inside, Outside או Both.','הגדירו עובי ובדקו חתך לאחר האישור.'],'דפנות בעובי מוגדר.','עובי גדול באזורים צרים עלול להיכשל.',['S11']);
add('חור עם שיקוע או הברזה','Solid > Create > Hole; H','גוף ונקודת מיקום מוגדרת.', ['הפעילו Hole והגדירו מיקום על הפאה או נקודות סקיצה.','בחרו Simple, Counterbore או Countersink.','הגדירו קוטר, עומק וסוג Tap לפי הצורך.','בדקו את כל המידות ואשרו.'],'חור מתועד כפעולת Hole.','אל תסתמכו על ברירת המחדל של קוטר או עומק.',['S12']);
add('הברגה פנימית או חיצונית','Solid > Create > Thread','פאה גלילית וקוד הברגה ידוע.', ['בחרו Thread ואז את הפאה הגלילית.','הגדירו תקן, מידה, Designation ו־Class.','הגדירו אורך וכיוון.','סמנו Modeled רק כשנדרשת גאומטריה ממשית.'],'הברגה תצוגתית או גאומטרית לפי הבחירה.','הברגה תצוגתית אינה יוצרת שיניים בקובץ הדפסה. התאמות ייצור נבדקות בנפרד.',['S12','P6']);
add('שכפול בשורות','Solid > Create > Pattern > Rectangular Pattern','פעולה או גוף שכבר נוצרו.', ['בחרו Object Type, למשל Features.','בחרו פעולה ב־Timeline וציר כיוון.','הגדירו Quantity ו־Spacing או Extent.','לשורה יחידה קבעו Quantity=1 בציר השני.'],'מערך חזרות הניתן לעריכה.','Spacing הוא מרווח; Extent הוא הטווח הכולל בין הקצוות.',['S13']);
add('שכפול סביב ציר','Solid > Create > Pattern > Circular Pattern','חור או רכיב וציר סיבוב.', ['בחרו Object Type ואובייקט.','בחרו Axis.','בחרו Full וכמות, או Partial וזווית.','בדקו מיקומים ואשרו.'],'חזרות זוויתיות, למשל חורי אוגן.','Quantity כולל את המופע המקורי; בדקו ספירה.',['S14']);
add('מישור אמצע ושיקוף','Construct > Midplane; Solid > Create > Mirror','שתי פאות מקבילות או מישור סימטריה קיים.', ['צרו Midplane בין שתי הפאות אם נדרש.','הפעילו Mirror ובחרו Features או Bodies.','בחרו אובייקטים ומישור Mirror Plane.','בדקו את הצד השני ואשרו.'],'גאומטריה סימטרית משני צדי המישור.','Mirror בסקיצה הוא כלי אחר; בדקו שאתם ב־Solid.',['P6']);
add('איחוד וחיסור בין גופים','Solid > Modify > Combine','לפחות שני גופים מוצקים.', ['בחרו Target Body שישתנה.','בחרו Tool Bodies.','בחרו Join, Cut או Intersect.','סמנו Keep Tools לשימור גופי הכלי ואשרו.'],'איחוד, חלל או נפח חפיפה.','Combine משנה גאומטריה; הוא אינו חיבור מכני בין רכיבים.',['S15']);
add('פיצול גוף','Solid > Modify > Split Body','גוף ומישור או משטח חותך.', ['בחרו Body to Split.','בחרו Splitting Tool.','אפשרו Extend Splitting Tool אם הכלי קצר.','אשרו ובדקו שני גופים ב־Browser.'],'גופים נפרדים שניתן לטפל בהם בנפרד.','Split Body שונה מ־Section Analysis שמשנה רק תצוגה.',['S16']);
add('יצירת פרמטרים','Solid > Modify > Change Parameters','בחרו שמות ברורים באותיות לטיניות.', ['לחצו Add User Parameter.','הגדירו Name ו־Unit.','הקלידו Expression, למשל 80 mm.','צרו גם width ו־thickness ואשרו.'],'טבלת מידות מרכזית.','השתמשו בשמות ייחודיים ובלי רווחים.',['S17']);
add('שימוש בפרמטר וביטוי','Sketch Dimension / Feature input','פרמטרים שהוגדרו מראש.', ['פתחו מידה או פעולת Extrude לעריכה.','החליפו מספר בשם הפרמטר.','לקשר מידות השתמשו בביטוי כגון width/2.','שנו פרמטר ובדקו את כל המודל.'],'שינוי אחד מעדכן את המידות התלויות בו.','ודאו שיחידות הביטוי תואמות לשדה.',['S17','P13']);
add('עריכת היסטוריית המודל','Timeline > Edit Feature / Edit Sketch','מודל פרמטרי עם היסטוריה.', ['אתרו את הפעולה המקורית ב־Timeline.','לחצו פעמיים לעריכה.','שנו את המידה ואשרו.','בדקו פעולות מאוחרות וסימוני שגיאה.'],'עדכון מבוקר בלי לבנות את החלק מחדש.','תיקון מתחיל בפעולה הראשונה שנכשלה, לא בכל ההשלכות שלה.',['P12','P1']);
chapter('03 מכלולים ובדיקות','בנו קשרים בין רכיבים, ואז בדקו חופש תנועה, מרחקים וחפיפות.');
add('יצירת רכיב פעיל','New Component; Activate','Hybrid Design לתרגול רכיבים פנימיים.', ['לחצו ימנית על רכיב האב ובחרו New Component.','בחרו סוג Part ותנו שם.','אשרו שהרכיב החדש פעיל.','צרו בתוכו סקיצות וגופים.'],'כל הגאומטריה שייכת לרכיב הנכון.','Bodies בתוך אותו Component אינם חלקים עצמאיים ל־Joint.',['S02','S03','P12']);
add('הכנסת חלק שמור למכלול','Data Panel > Insert into Current Design','מכלול פתוח וקובץ Fusion שמור.', ['פתחו את Data Panel.','אתרו את החלק ולחצו עליו ימנית.','בחרו Insert into Current Design.','מקמו בקירוב ואשרו; מיקום מדויק קבעו בקשרים.'],'רכיב חיצוני מקושר מופיע במכלול.','אין בכך יצירת עותק עצמאי; הקובץ החיצוני נשאר מקור.',['S18']);
add('עותק זהה או עצמאי','Copy > Paste / Paste New','רכיב פנימי ב־Hybrid; בחרו הורה מתאים.', ['בחרו Component ב־Browser ובצעו Copy.','בחרו את רכיב האב כיעד.','בחרו Paste לעותק משותף או Paste New לעצמאי.','בדקו שינוי קטן כדי לוודא את התלות.'],'העותק מתנהג לפי בחירתכם.','עותק Paste משותף יכול להשתנות כשעורכים את המקור.',['S18','P13']);
add('קיבוע בסיס המכלול','Pin','רכיב בסיס במיקום הרצוי.', ['בחרו את רכיב הבסיס.','הפעילו Pin מתפריט הרכיב.','בדקו את הופעת הפעולה ב־Timeline.','נסו להזיז: הבסיס צריך להישאר במקום.'],'עוגן במערכת הצירים של התכנון.','בסרטונים ישנים מופיע Ground; הבדילו מהפקודה הנוכחית Ground To Parent.',['S19']);
add('קיבוע רכיב להורה','Ground To Parent','רכיב שצריך לנוע יחד עם רכיב האב.', ['בחרו רכיב ב־Browser.','הפעילו Ground To Parent.','בדקו חזרה למיקום ההתחלתי.','בדקו שקשרים קיימים לא נפגעו.'],'הבן וההורה נעים יחד.','הפקודה יכולה לגבור על Move, Pin או Capture Position קיימים.',['S20']);
add('חיבור ומיקום שני רכיבים','Solid > Assemble > Joint; J','שני Components; הראשון מיועד לנוע.', ['בחרו נקודת Joint Origin על הרכיב הראשון.','בחרו נקודת התאמה ברכיב השני.','תקנו Flip, Offset או Angle.','בחרו Motion Type ובצעו Preview לפני OK.'],'הרכיב ממוקם ונקבעה התנועה היחסית.','אם הראשון מקובע, בדקו Pin וקשרים קיימים לפני שינוי.',['S21']);
add('חיבור קשיח במיקום קיים','Assemble > As-Built Joint > Rigid','הרכיבים כבר במקומם.', ['הפעילו As-Built Joint.','בחרו שני רכיבים.','בחרו Rigid.','אשרו ונסו לגרור אחד מהם.'],'אין תנועה יחסית ביניהם.','As-Built אינו מתקן מיקום שגוי שהוגדר קודם.',['S22']);
add('מפרק סיבובי','Joint / As-Built Joint > Revolute','ציר או זרוע ותושבת נפרדת.', ['בחרו את שני הרכיבים.','הגדירו Origin במרכז הסיבוב.','בחרו Revolute ואת ציר הסיבוב.','הציגו Preview ואשרו.'],'דרגת חופש אחת של סיבוב.','מרכז שגוי יגרום למסלול סיבוב שגוי גם אם החלק נראה מחובר.',['S21']);
add('מפרק החלקה או גלילי','As-Built Joint > Slider / Cylindrical','רכיבים ממוקמים על ציר משותף.', ['בחרו שני רכיבים ב־As-Built Joint.','בחרו Slider לתרגום בלבד או Cylindrical לתרגום וסיבוב.','הגדירו Snap וציר.','בדקו Preview ואשרו.'],'חופש תנועה תואם למנגנון.','Slider אינו מאפשר סיבוב סביב הציר.',['S22']);
add('גבולות תנועה','Joint Motion Limits','מפרק שאינו Rigid.', ['פתחו את הגדרת המפרק.','בחרו דרגת תנועה אם יש כמה.','הפעילו Minimum, Maximum ו־Rest.','הקלידו ערכים ובדקו את הטווח.'],'המנגנון נשאר בתוך הטווח שהוגדר.','הגבולות אינם מחושבים אוטומטית לפי התנגשויות.',['S22']);
add('בדיקת המפרק בתוך המכלול','Animate Joint Relationships','Joint קיים ושאר קשרי המכלול מוגדרים.', ['אתרו את המפרק ב־Browser.','בחרו Animate Joint Relationships.','עקבו אחר כל הרכיבים התלויים.','עצרו ותיקנו קשרים אם התנועה אינה הרצויה.'],'נבדקת התנהגות עם קשרי המכלול.','Animate Joint לבדו מתעלם מהשפעת קשרים אחרים; אינו אותה בדיקה.',['S21']);
add('יחס תנועה בין שני צירים','Assemble > Motion Link','שני מפרקים עם דרגות חופש מתאימות.', ['בחרו את שני ה־Joints.','בחרו את דרגת התנועה של כל אחד.','הקלידו ערכים יחסיים; לדוגמה 360° ו־180°.','בדקו Reverse והפעילו Animate.'],'בדוגמה: השני מסתובב חצי סיבוב לכל סיבוב ראשון.','זה יחס קינמטי; אין כאן חישוב מומנט, חיכוך או התנהגות שרשרת.',['S24']);
add('יישור באמצעות אילוצי מכלול','Assemble > Constrain Components','שני Components ללא אילוצים סותרים.', ['בחרו Type: Align.','בחרו פאה, קצה או נקודה ברכיב הראשון.','בחרו גאומטריה תואמת בשני.','הגדירו Offset או Flip ואשרו.'],'יחס מישורי, צירי או נקודתי לפי הבחירה.','הכלי שונה מ־Modify > Align; אילוץ יחיד לא בהכרח מבטל כל חופש.',['S25']);
add('מדידת מרחק וקוטר','Inspect > Measure; I','ישויות גאומטריות מוגדרות במודל.', ['פתחו Measure.','בחרו פאה או קצה לקריאת קוטר או אורך.','בחרו ישות נוספת לקריאת מרחק או זווית.','במידת הצורך הפעילו XYZ Delta.'],'מדידה מדויקת לפי הבחירות.','מרחק בין מרכזים ומרחק מינימלי בין משטחים הם גדלים שונים.',['S26']);
add('בדיקת התנגשויות','Inspect > Interference','שני גופים או רכיבים לפחות.', ['בחרו רכיבים לבדיקה.','סמנו Include Coincident Faces רק אם רוצים גם מגע.','לחצו Compute.','עברו על זוגות עם נפח חפיפה חיובי.'],'זיהוי חפיפה במצב ההרכבה הנוכחי.','אין חפיפה במצב אחד אינו מוכיח שאין חפיפה לאורך כל התנועה.',['S27']);
add('מבט חתך לבדיקה פנימית','Inspect > Section Analysis','מישור חיתוך או פאה שטוחה.', ['בחרו Section Analysis.','בחרו Cut Plane.','הגדירו Offset וזווית; Flip מחליף צד.','אשרו והדליקו או כבו דרך Analysis.'],'רואים חללים וממשקים פנימיים.','זו תצוגה בלבד; הגאומטריה המקורית לא נחתכת.',['S28']);
add('הגדרת חומר הנדסי','Physical Material','גוף או רכיב שמידלנו.', ['פתחו Physical Material דרך חיפוש S.','אתרו חומר מתאים בספרייה.','גררו אותו אל הגוף או הרכיב.','בדקו שהוחל על האובייקט הנכון.'],'למודל משויכות תכונות חומר.','Appearance משנה מראה בלבד, ולכן אינו מחליף הגדרת חומר.',['S29']);
chapter('04 שרטוט ויצוא','הפיקו תיעוד מהמודל, בדקו מידות ורק אז ייצאו לפורמט המתאים.');
add('פתיחת שרטוט ייצור','Workspace > Drawing > From Design','תכנון שמור.', ['בחרו From Design וסוג Manual.','בחרו רכיבים או Full Assembly.','קבעו Standard, יחידות וגודל דף.','אשרו ושמרו את מסמך השרטוט.'],'מסמך שרטוט המקושר לתכנון.','בחירת ISO או ASME אינה מחליפה בדיקת תקן השרטוט הנדרש.',['S30']);
add('מבט ראשי','Drawing > Create > Base View','גיליון שרטוט פתוח.', ['בחרו Reference וייצוג Model.','בחרו Orientation.','הגדירו Scale וסגנון קווים.','מקמו ואשרו.'],'מבט בסיס שעליו יסתמכו מבטים נוספים.','קנה המידה של המבט אינו משנה את ממדי החלק.',['S31']);
add('מבטים מוקרנים','Drawing > Create > Projected View','מבט בסיס קיים.', ['הפעילו Projected View.','בחרו את מבט האב.','הזיזו לצד הרצוי והציבו מבטים.','סיימו ואמתו את כיוון ההיטל.'],'מבטים קשורים ומיושרים למבט האב.','בדקו שיטת היטל במסמך; אל תזהו צד רק לפי מיקום על הדף.',['S32']);
add('חתך בשרטוט','Drawing > Create > Section View','מבט אב שמציג את אזור החיתוך.', ['בחרו את מבט האב.','סמנו התחלה וסוף של קו החתך.','לחצו Enter והציבו את מבט החתך.','בדקו כיוון, עומק וקנה מידה ואשרו.'],'מבט פנימי עם סימון חתך.','חתך שרטוט שונה מ־Section Analysis בתלת־ממד.',['S33']);
add('מידות וסימוני מרכז','Drawing > Dimensions; Geometry > Center Mark','מבטים שמאפשרים למדוד את התכונה.', ['בחרו Dimension.','בחרו קצוות או נקודות והציבו את המידה.','השתמשו Diameter או Radius לפי הצורך.','הוסיפו Center Mark לחורים ובדקו שאין כפילויות.'],'מידות קריאות שמקושרות לגאומטריה.','שינוי טקסט מידה אינו שינוי של המודל; תקנו את החלק במקור.',['S32']);
add('רשימת חלקים ובלונים','Drawing > Tables > Parts List','מבט מכלול עם Components.', ['בחרו Parts List ואת המבט שאליו היא קשורה.','בחרו First Level או All Levels.','מקמו את הטבלה ובדקו את הבלונים.','עדכנו שמות ותיאורים ב־Properties של הרכיבים.'],'רשימת חלקים המקושרת למכלול.','גוף נוסף בתוך רכיב אינו בהכרח שורת רכש עצמאית.',['S34']);
add('יצוא שרטוט ורשימת חלקים','Drawing > Export > PDF / CSV','שרטוט מעודכן וטבלה לפי הצורך.', ['לשרטוט בחרו Export PDF.','בחרו גיליונות ויעד שמירה.','לטבלה בחרו Export CSV ואת הטבלה.','פתחו את הקבצים ובדקו שכל הנתונים יצאו.'],'PDF לצפייה ו־CSV לפתיחה באקסל.','אפשרויות יצוא תלויות ברישיון; בדקו מה זמין אצלכם.',['S35']);
add('יצוא מודל ל־CAD אחר','File > Export > STEP','תכנון שמור והחלקים הנכונים נכללים.', ['בחרו Export.','בחרו STEP.','קבעו שם ויעד ואשרו.','פתחו את הקובץ מחדש ובדקו יחידות וגאומטריה.'],'מודל גאומטרי להעברה למערכת CAD אחרת.','STEP אינו שומר את ה־Timeline של Fusion.',['S36']);
add('גיבוי לעריכה עתידית','File > Export > Fusion Archive','תכנון שמור, כולל קישורים אם יש.', ['בחרו יצוא בפורמט Fusion המקורי.','שמרו F3D או ארכיון מכלול מתאים לפי התכנון.','תנו שם עם זיהוי גרסה.','בדקו שניתן לפתוח את הארכיון.'],'גיבוי המכיל נתוני עריכה של Fusion.','אל תשמרו רק STL או STEP אם תרצו היסטוריית תכנון.',['S36']);
add('קובץ להדפסה בתלת־ממד','Browser > Save As Mesh','גוף תקין בגודל הרצוי.', ['לחצו ימנית על הגוף או הרכיב ובחרו Save As Mesh.','בחרו 3MF או STL.','בחרו Unit Type ו־One File או One Body Per File.','שמרו ופתחו בסלייסר לבדיקת גודל.'],'רשת להדפסה ביחידות שנבחרו.','בדקו שהסלייסר לא פירש מילימטרים כאינצ׳ים.',['S37']);
chapter('05 הדמיה ופח','הדמיות להסבר והרכבה; פעולות פח בסיסיות לפריסה.');
add('מראה וצבע','Appearance; A','גוף, רכיב או פאה.', ['פתחו Appearance.','בחרו חומר חזותי.','גררו לרכיב או לפאה המתאימים.','בדקו את היקף ההחלה.'],'צבע ומרקם להבחנה בין חלקים.','המראה אינו משנה תכונות הנדסיות של החומר.',['S29']);
add('רינדור מקומי ושמירת תמונה','Render > In-canvas Render > Capture Image','סביבת Render; מראה ומבט כבר מוגדרים.', ['הפעילו In-canvas Render.','הגדירו איכות ב־In-canvas Render Settings.','המתינו להתכנסות בלי להזיז את המצלמה.','בחרו Capture Image ושמרו.'],'תמונה של המודל בתאורה וחומרים.','הזזת המבט מתחילה חישוב מחדש; לכידה מקומית תלויה בגודל חלון התצוגה.',['S42']);
add('פירוק אוטומטי להדמיה','Animation > Transform > Auto Explode','מכלול עם רכיבים נפרדים.', ['עברו ל־Animation.','בחרו רכיבים למופע.','בחרו Auto Explode ברמה אחת או בכל הרמות.','בדקו את הפירוק והשלימו ידנית אם צריך.'],'מבט מפורק להסבר מבנה המכלול.','פירוק אוטומטי אינו קובע סדר הרכבה הנדסי.',['S38']);
add('פירוק ידני לאורך ציר','Animation > Transform Components','רכיבים נפרדים ו־Storyboard פתוח.', ['מקמו את ראש הזמן בזמן הרצוי.','בחרו רכיב ו־Transform Components.','הקלידו מרחק X/Y/Z או זווית סיבוב.','אשרו ונגנו את הפעולה.'],'פעולת הזזה או סיבוב בציר הזמן.','תנועת Animation היא הצגה; היא אינה בדיקת Joint מכני.',['S39']);
add('החזרת חלק למצב מורכב','Animation > Transform > Restore Home','רכיב שהוזז בהדמיה.', ['בחרו את הרכיב.','מקמו את ראש הזמן.','הפעילו Restore Home.','בדקו שהתנועה מסתיימת במיקום התכנון.'],'אנימציית חזרה למצב המקורי.','Home מתייחס למיקום בתכנון, לא לתנוחת מצלמה.',['S39']);
add('יצוא סרטון','Animation > Publish > Publish Video','Storyboard שנבדק בניגון.', ['בחרו Publish Video.','בחרו Current Storyboard או Document.','בחרו רזולוציה ושמרו יחס ממדים.','אשרו יעד ושמרו את הסרטון.'],'קובץ וידאו של ההדמיה.','בחרו Current Storyboard אם אין צורך בכל הסצנות.',['S40']);
add('שרטוט של מכלול מפורק','Drawing > From Animation','Storyboard עם מצב מפורק רצוי.', ['בחרו From Animation.','בחרו את ה־Storyboard כמקור.','קבעו תקן, יחידות וגודל דף.','הציבו Base View ובדקו את מצב הפירוק.'],'מבט מפורק בשרטוט, שאפשר להוסיף לו רשימת חלקים.','בחרו את ה־Storyboard הנכון; מצב המבט נגזר מההדמיה.',['S41']);
add('בסיס פח עם כלל מתאים','Sheet Metal > Create > Flange','סקיצה סגורה ומפרט עובי וכיפוף.', ['בחרו Flange מסוג Base/Edge/Contour.','בחרו פרופיל סגור.','בחרו Sheet Metal Rule ובדקו עובי וחומר.','קבעו Orientation ו־Operation ואשרו.'],'גוף פח בעל כלל מוגדר.','עובי ורדיוס כיפוף הם נתוני ייצור, לא ערכים שמעתיקים מתרגיל.',['S43','S44']);
add('דופן מכופפת','Sheet Metal > Create > Flange','גוף פח עם קצה מתאים.', ['הפעילו Flange ובחרו קצה.','הגדירו Height ו־Angle.','בדקו Height Datum ו־Bend Position.','בדקו מרווח בפינות ואשרו.'],'דופן עם כיפוף לפי כלל הפח.','אותו גובה נומינלי ייתן תוצאה שונה אם בסיס המדידה משתנה.',['S43']);
add('פריסת פח','Sheet Metal > Create > Create Flat Pattern','רכיב פח עם גוף אחד ופאה שטוחה.', ['הפעילו Create Flat Pattern.','בחרו פאה נייחת.','אשרו ובדקו את הפריסה.','חזרו במקש Finish Flat Pattern; אחרי שינוי עדכנו את הפריסה.'],'פריסה המקושרת לגוף המכופף.','דיוק אורך הפריסה תלוי בכלל הכיפוף ובהתאמה לתהליך הייצור.',['S45']);
src('G1','Kevin McAleer — Creating Gears in Fusion 360','https://www.kevsrobots.com/blog/creating-gears-in-fusion-360.html','SpurGear, מודול וקוטר חלוקה; המקור כולל גם מסרק','פורסם 06.10.2025; עודכן 17.11.2025');
src('G2','Autodesk — create gears with SpurGear','https://help.autodesk.com/view/fusion360/ENU/?caas=caas/sfdcarticles/sfdcarticles/How-to-create-a-spur-Gear-in-Fusion-360.html','Utilities → Scripts and Add-Ins → SpurGear → Run','עודכן 14.09.2026');
